<section class="page-heading"><div><p class="eyebrow"><?= e(implode(' · ',array_filter([$outfit['occasion'],$outfit['season']])) ?: 'MA TENUE') ?></p><h1><?= e($outfit['name']) ?></h1><p class="subheading"><?= e($outfit['style'] ?: 'Style à définir') ?> · Portée <?= e($outfit['wear_count']) ?> fois</p></div><div class="heading-actions"><a class="button secondary back-button" href="<?= e(url('outfits')) ?>">&larr; Retour aux tenues</a><a class="button secondary" href="<?= e(url('outfits-edit',['id'=>$outfit['id']])) ?>">Modifier</a><form method="post" action="<?= e(url('outfits-favorite')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($outfit['id']) ?>"><button class="button secondary" type="submit"><?= $outfit['is_favorite']?'♥ Favori':'♡ Ajouter aux favoris' ?></button></form></div></section>
<?php if($outfit['status']==='archived'): ?><div class="flash warning">Cette tenue est archivée. <form method="post" action="<?= e(url('outfits-restore')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($outfit['id']) ?>"><button class="button primary">Restaurer</button></form></div><?php endif; ?>
<?php if($outfit['description']): ?><p class="outfit-description"><?= nl2br(e($outfit['description'])) ?></p><?php endif; ?>

<?php if($items): ?><section class="outfit-composition"><div class="section-head"><div><p class="eyebrow">VOTRE COMPOSITION COMPLÈTE</p><h2><?= count($items) ?> pièce<?= count($items)>1?'s':'' ?> réunies</h2></div></div><div class="outfit-collage outfit-detail-collage" aria-label="Composition complète de <?= e($outfit['name']) ?>"><?php foreach($items as $item): ?><a class="outfit-collage-piece" href="<?= e(url('clothes-show',['id'=>$item['id']])) ?>" title="<?= e($item['name']) ?>"><?php if($item['image_path']): ?><img loading="lazy" src="<?= e(APP_BASE_URL.'/'.$item['image_path']) ?>" alt="<?= e($item['name']) ?>"><?php else: ?><span><?= e(mb_strtoupper(mb_substr($item['name'],0,1))) ?></span><?php endif; ?><small><?= e($item['name']) ?></small></a><?php endforeach; ?></div></section><?php elseif($outfit['cover_path']): ?><div class="outfit-cover-fallback"><img src="<?= e(APP_BASE_URL.'/'.$outfit['cover_path']) ?>" alt="Couverture de <?= e($outfit['name']) ?>"></div><?php endif; ?>
<section class="section-head"><div><p class="eyebrow">LES PIÈCES DE LA TENUE</p><h2><?= count($items) ?> pièce<?= count($items)>1?'s':'' ?></h2></div><div class="heading-actions"><form method="post" action="<?= e(url('outfits-wear')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($outfit['id']) ?>"><button class="button primary" type="submit">✓ Marquer comme portée</button></form></div></section>
<?php if(!$items): ?><div class="empty-state"><h3>Aucune pièce dans cette tenue</h3><p>Modifiez-la pour ajouter les éléments de votre garde-robe.</p></div><?php else: ?><div class="clothes-grid"><?php foreach($items as $item): ?><a class="clothing-card" href="<?= e(url('clothes-show',['id'=>$item['id']])) ?>"><div class="clothing-photo"><?php if($item['image_path']): ?><img src="<?= e(APP_BASE_URL.'/'.$item['image_path']) ?>" alt="<?= e($item['name']) ?>"><?php else: ?><span>GRINGO</span><?php endif; ?><?php if($item['status']!=='available'): ?><span class="status-pill"><?= e(['laundry'=>'Au lavage','repair'=>'À réparer','unavailable'=>'Indisponible'][$item['status']]??'Indisponible') ?></span><?php endif; ?></div><div class="clothing-meta"><span><?= e($item['label_name']) ?></span><h3><?= e($item['name']) ?></h3></div></a><?php endforeach; ?></div><?php endif; ?>
<section class="outfit-rating-panel"><div><p class="eyebrow">VOTRE AVIS</p><h2>Notez cette tenue</h2><?php $rating=$outfit['rating']; require APP_ROOT.'/app/views/partials/rating-display.php'; ?></div><?php $ratingAction='outfits-rate';$ratingObjectId=(int)$outfit['id'];$ratingContext='outfit';$ratingLegend='Votre note sur 5';require APP_ROOT.'/app/views/partials/rating-form.php'; ?></section>
<div class="outfit-secondary-actions"><form method="post" action="<?= e(url('outfits-duplicate')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($outfit['id']) ?>"><button class="button secondary" type="submit">⧉ Dupliquer</button></form><form method="post" action="<?= e(url('outfits-delete')) ?>" data-confirm="Archiver cette tenue ?"><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($outfit['id']) ?>"><button class="button danger" type="submit">Archiver</button></form><form method="post" action="<?= e(url('outfits-delete-permanent')) ?>" data-confirm="Suppression definitive : la tenue, son historique, ses favoris et son contenu seront supprimes. Ses dates de calendrier seront conservees sans tenue associee. Cette action est irreversible. Continuer ?"><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($outfit['id']) ?>"><button class="button danger" type="submit">Supprimer definitivement</button></form></div>
<?php if($history): ?><section class="history-panel"><p class="eyebrow">HISTORIQUE</p><h2>Portée récemment</h2><?php foreach($history as $event): ?><div class="detail-row"><span><?= e(date('d.m.Y H:i',strtotime($event['worn_at']))) ?></span><strong><?= e($event['note']?:'Portée') ?></strong></div><?php endforeach; ?></section><?php endif; ?>
